const server = app.listen(3000);
let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;          // ignore a second signal
  shuttingDown = true;
  logger.info({ signal }, 'shutting down');

  // Hard limit: never hang forever. unref so it does not keep us alive.
  setTimeout(() => {
    logger.error('forced shutdown');
    process.exit(1);
  }, 10_000).unref();

  try {
    // 1. Stop accepting connections; resolves when in-flight requests finish
    await new Promise((resolve, reject) =>
      server.close((err) => (err ? reject(err) : resolve())));
    // 2. Close other resources
    await consumer.stop();
    await db.end();
    await redis.quit();
    process.exitCode = 0;
  } catch (err) {
    logger.error(err, 'error during shutdown');
    process.exitCode = 1;
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

